export function buildPlan(input, sources = []) {
  const { name, audience, hypothesis, method, participants, days, decision } = input || {};
  const warnings = [];
  const p = Number(participants) || 0;
  const d = Number(days) || 0;

  if (p <= 0) warnings.push('Participants must be greater than 0.');
  if (d <= 0) warnings.push('Days must be greater than 0.');

  const schedule = [];
  if (d > 0) {
    for (let i = 1; i <= d; i++) {
      let label = `Day ${i}`;
      if (i === 1) label += ' (Recruit)';
      else if (i === d) label += ' (Decide)';
      else if (i === 2) label += ' (Collect)';
      else if (i === d - 1) label += ' (Synthesize)';
      else label += ' (Collect)';
      schedule.push({ day: i, label });
    }
  }

  const questions = [
    `What is your biggest challenge with ${audience || 'your target audience'}?`,
    `Can you walk me through how you currently handle ${method || 'research'}?`,
    `What would make this process significantly easier for you?`,
    `If you could change one thing about your current workflow, what would it be?`
  ];

  const summary = `Plan for "${name || 'Untitled Study'}" to test: "${hypothesis || 'No hypothesis provided'}".`;

  return {
    summary,
    metrics: [
      { label: 'Target participants', value: p },
      { label: 'Study days', value: d },
      { label: 'Evidence count', value: sources.length }
    ],
    sections: [
      {
        title: 'Hypothesis (Untested)',
        items: [hypothesis || 'No hypothesis provided']
      },
      {
        title: 'Interview Questions',
        items: questions
      },
      {
        title: 'Study Schedule',
        items: schedule.map(s => s.label)
      },
      {
        title: 'Decision',
        items: [decision || 'No decision specified. Revisit when ready.']
      }
    ],
    warnings,
    name,
    audience,
    hypothesis,
    method,
    participants: p,
    days: d,
    decision,
    questions,
    schedule,
    evidence_count: sources.length,
    sources
  };
}

